    const heure = d.toLocaleTimeString('fr-FR', { timeZone: 'Africa/Tunis', hour: 'numeric', minute: '2-digit' }).replace(':', ' h ');
    const auj = jour(new Date()), hier = jour(new Date(Date.now() - 86400000));
