    const corps = `${tete(sousTete)}${bandHors}${bandLs}${recherche}${tel && !ap ? telNav : ''}<div class="cl-g${ap ? '' : ' sans-ap'}">${tel ? '' : arbre}<div class="cl-liste"${tel && ap ? ' hidden' : ''}>${milieu}</div>${ap}</div>`;
